import{_ as e,o as a,c as n,ap as o}from"./chunks/framework.CuFS6FqL.js";const u=JSON.parse('{"title":"Starting and closing the day","description":"Optional morning set-up and evening tear-down. Calendar, urgent mail, and a todo list so unfinished work does not follow you home (Zeigarnik effect).","frontmatter":{"title":"Starting and closing the day","description":"Optional morning set-up and evening tear-down. Calendar, urgent mail, and a todo list so unfinished work does not follow you home (Zeigarnik effect)."},"headers":[],"relativePath":"organization/human-resources/starting-and-closing-the-day.md","filePath":"organization/human-resources/starting-and-closing-the-day.md"}'),i={name:"organization/human-resources/starting-and-closing-the-day.md"};function s(r,t,l,d,c,h){return a(),n("div",null,[...t[0]||(t[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/starting-and-closing-the-day.md for this page in Markdown format</div><h1 id="starting-and-closing-the-day" tabindex="-1">Starting and closing the day <a class="header-anchor" href="#starting-and-closing-the-day" aria-label="Permalink to &quot;Starting and closing the day&quot;">​</a></h1><p>A suggestion, not a rule.</p><h2 id="☀️-set-up-start-of-day" tabindex="-1">☀️ Set up (start of day) <a class="header-anchor" href="#☀️-set-up-start-of-day" aria-label="Permalink to &quot;☀️ Set up (start of day)&quot;">​</a></h2><p>Morning set up and before deep work: know what is committed and what to do next.</p><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Check the calendar (meetings, standups, travel). Plan around those blocks.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Check emails. Handle urgent and important. Rest is optional. (Repond within 1 business day.)</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Check your todo list. Start with the next concrete action from yesterday&#39;s tear-down.</li></ul><h2 id="🌇-tear-down-close-of-day" tabindex="-1">🌇 Tear down (close of day) <a class="header-anchor" href="#🌇-tear-down-close-of-day" aria-label="Permalink to &quot;🌇 Tear down (close of day)&quot;">​</a></h2><p>Evening tear down: plan the following day(s) so you can disconnect.</p><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Check emails for urgent and important messages. Rest is optional.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Check the next days in the calendar, not only tomorrow.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Write the todo list for the following days as concrete next actions, on the days they belong. Even if you think you will remember.</li></ul><p>Unfinished tasks occupy working memory more than finished ones (<a href="https://en.wikipedia.org/wiki/Zeigarnik_effect" target="_blank" rel="noreferrer">Zeigarnik effect</a>). Useful during the day, costly after work.<br> Write the evening todo list to park those loops, then stop. Morning set-up reopens the list on purpose.</p>',10)])])}const g=e(i,[["render",s]]);export{u as __pageData,g as default};
